            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        elif nbytes == 2:
            return value
        else:
            raise ValueError(f"Invalid nbytes for register read: {nbytes}")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr in [0x00, 0x01, 0x02, 0x03, 0x04, 0xFC, 0xFD, 0xFE, 0xFF]:
            # Read-only registers
            return

        if nbytes == 1:
            current_value = self.regs[addr]
            self.regs[addr] = (current_value & 0xFF) | (data << 8)
        elif nbytes == 2:
            self.regs[addr] = data
        else:
